package cn.binbin.crm;
import jakarta.validation.*;import jakarta.validation.constraints.*;import java.time.*;import java.util.*;import org.springframework.stereotype.Service;import com.fasterxml.jackson.databind.DeserializationFeature;import static cn.binbin.crm.TradeService.*;import static cn.binbin.crm.P3Base.map;
@Service
public class IntegrationService {
 public record Query(@NotNull @Pattern(regexp="ORDER|INVOICE|EXPENSE|TARGET|COMMISSION|WEEKLY|PRODUCT") String entityType,UUID recordId,@Min(1) @Max(100000) int page,@Min(1) @Max(100) int pageSize,@Size(max=100) String q,@Min(2000) @Max(2100) int year){}
 static final Map<String,String> READ_SCOPES=Map.of("orders.read","ORDER","invoices.read","INVOICE","expenses.read","EXPENSE","targets.read","TARGET","commissions.read","COMMISSION","weeklies.read","WEEKLY","products.read","PRODUCT");
 public record KeyInput(@NotBlank @Size(max=100) String name,@NotNull UUID ownerMemberId,@NotEmpty @Size(max=20) List<@NotBlank String> scopes,@Min(1) @Max(365) int expiresDays){}
 public record Decision(@Min(0) long expectedVersion){}
 public record HookInput(@NotBlank @Size(max=100) String name,@NotBlank @Size(max=2048) String url,@NotNull UUID ownerMemberId,@NotEmpty @Size(max=32) List<@NotBlank String> events,boolean active,@Min(0) long expectedVersion){}
 static final Set<String> SCOPES=Set.of("contacts.create","leads.create","tickets.create","orders.read","invoices.read","expenses.read","targets.read","commissions.read","weeklies.read","products.read");static final Set<String> EVENTS=Set.of("customer.created","customer.updated","lead.created","lead.updated","opportunity.created","opportunity.updated","ticket.created","ticket.updated","receipt.created","receipt.updated","campaign.created","campaign.updated","quote.created","quote.updated","order.created","order.updated","contract.created","contract.updated","invoice.created","invoice.updated","expense.created","expense.updated","target.created","target.updated","commission.created","commission.updated","weekly.created","weekly.updated");
 private final P3Base b;private final ServiceDeskService desk;private final CampaignService campaigns;private final FinanceService finance;private final IntegrationCrypto vault;private final WebhookTransport transport;private final Validator validator;private final P7Records records;
 public IntegrationService(P3Base b,ServiceDeskService desk,CampaignService campaigns,FinanceService finance,IntegrationCrypto vault,WebhookTransport transport,Validator validator,P7Records records){this.b=b;this.desk=desk;this.campaigns=campaigns;this.finance=finance;this.vault=vault;this.transport=transport;this.validator=validator;this.records=records;}
 private long epoch(AuthService.Actor a){return b.db.queryForObject("SELECT auth_version FROM iam_user WHERE id=:id",map("id",a.session().userId()),Long.class);}
 private void canScope(AuthService.Actor a,String scope){boolean ok=switch(scope){case "contacts.create"->a.businessAccess().contactWrite()&&a.canReadCustomers();case "leads.create"->a.businessAccess().leads().write();case "tickets.create"->a.p3Access().tickets().write();default->READ_SCOPES.containsKey(scope)&&records.allowed(a,READ_SCOPES.get(scope),false);};if(!ok)throw ApiError.forbidden("接口归属成员没有对应业务权限");}
 private List<String> strings(Object raw){try{return raw instanceof List<?> values?values.stream().map(String::valueOf).toList():b.data.json.readValue(String.valueOf(raw),new com.fasterxml.jackson.core.type.TypeReference<List<String>>(){});}catch(Exception e){throw new IllegalStateException("Integration metadata invalid");}}
 private void creator(UUID tenant,UUID member){var a=b.actor(tenant,member);if(!a.p3Access().integrationManage())throw ApiError.forbidden("集成管理授权已撤销");}
 private Map<String,Object> key(AuthService.Actor a,UUID id){return b.one("SELECT id,name,scopes,owner_member_id,created_by_member_id,expires_at,revoked_at,version,created_at,updated_at FROM crm_integration_key WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",id));}
 public Object keys(AuthService.Session s){return b.scoped(s,"integration",false,a->map("items",b.rows("SELECT k.id,k.name,k.scopes,k.owner_member_id,m.display_name AS owner_name,k.expires_at,k.revoked_at,k.version,k.created_at,k.updated_at FROM crm_integration_key k JOIN sys_tenant_member m ON m.tenant_id=k.tenant_id AND m.id=k.owner_member_id WHERE k.tenant_id=:tenant ORDER BY k.created_at DESC",map("tenant",a.tenant().id())),"vaultConfigured",vault.configured(),"scopes",new TreeSet<>(SCOPES),"events",new TreeSet<>(EVENTS),"protocol",map("timestampWindowSeconds",300,"requestsPerMinute",60,"basePath","/api/v1/inbound","signature","HMAC-SHA256","delivery","at-least-once")));}
 public Object owners(AuthService.Session s){return b.scoped(s,"integration",false,a->b.rows("SELECT m.id,m.display_name AS name FROM sys_tenant_member m JOIN iam_user u ON u.id=m.user_id WHERE m.tenant_id=:tenant AND m.status='ACTIVE' AND u.status='ACTIVE' AND NOT u.must_change_password ORDER BY m.display_name,m.id",map("tenant",a.tenant().id())));}
 public Object createKey(AuthService.Session s,KeyInput i,UUID trace){return b.scoped(s,"integration",true,a->{if(new HashSet<>(i.scopes()).size()!=i.scopes().size()||!SCOPES.containsAll(i.scopes()))throw ApiError.bad("接口授权范围无效");var owner=b.actor(a.tenant().id(),i.ownerMemberId());i.scopes().forEach(sc->canScope(owner,sc));if(b.db.queryForObject("SELECT count(*) FROM crm_integration_key WHERE tenant_id=:tenant AND revoked_at IS NULL AND expires_at>now()",map("tenant",a.tenant().id()),Integer.class)>=20)throw ApiError.bad("每个企业最多20个有效接口密钥");UUID id=UUID.randomUUID();String token=a.tenant().id()+"."+id+"."+Crypto.token();b.db.update("INSERT INTO crm_integration_key(id,tenant_id,name,token_hash,scopes,owner_member_id,owner_auth_version,created_by_member_id,expires_at) VALUES(:id,:tenant,:name,:hash,cast(:scopes AS jsonb),:owner,:epoch,:creator,:expires)",map("id",id,"tenant",a.tenant().id(),"name",text(i.name()),"hash",Crypto.hash(token),"scopes",b.json(i.scopes()),"owner",i.ownerMemberId(),"epoch",epoch(owner),"creator",a.tenant().memberId(),"expires",Instant.now().plusSeconds(i.expiresDays()*86400L)));b.audit(a,"INTEGRATION_KEY_CREATED","INTEGRATION_KEY",id,0,trace);return map("key",key(a,id),"oneTimeToken",token);});}
 public Object keyAction(AuthService.Session s,UUID id,String action,Decision i,UUID trace){return b.scoped(s,"integration",true,a->{var current=key(a,id);b.version(current,i.expectedVersion());if(current.get("revokedAt")!=null)throw ApiError.conflict("密钥已撤销");String token=null;if(action.equals("rotate")){var owner=b.actor(a.tenant().id(),(UUID)current.get("ownerMemberId"));strings(current.get("scopes")).forEach(sc->canScope(owner,sc));if(!ServiceDeskService.time(current,"expiresAt").isAfter(Instant.now()))throw ApiError.conflict("密钥已过期，请重新创建");token=a.tenant().id()+"."+id+"."+Crypto.token();b.db.update("UPDATE crm_integration_key SET token_hash=:hash,owner_auth_version=:epoch,created_by_member_id=:creator,version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",id,"hash",Crypto.hash(token),"epoch",epoch(owner),"creator",a.tenant().memberId()));}else if(action.equals("revoke"))b.db.update("UPDATE crm_integration_key SET revoked_at=now(),version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",id));else throw ApiError.bad("密钥动作无效");b.audit(a,"INTEGRATION_KEY_"+action.toUpperCase(Locale.ROOT),"INTEGRATION_KEY",id,i.expectedVersion()+1,trace);return map("key",key(a,id),"oneTimeToken",token);});}
 private <T>T parse(String body,Class<T> type){try{var mapper=b.data.json.copy().enable(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES);T input=mapper.readValue(body,type);if(input==null||!validator.validate(input).isEmpty())throw ApiError.bad("接口字段校验未通过");return input;}catch(ApiError e){throw e;}catch(Exception e){throw ApiError.bad("接口 JSON 格式或字段无效");}}
 public Object inbound(String authorization,String path,String timestamp,String nonce,String signature,String idempotency,String body,UUID trace){if(authorization==null||!authorization.matches("Bearer [a-f0-9-]{36}\\.[a-f0-9-]{36}\\.[A-Za-z0-9_-]{43}")||timestamp==null||!timestamp.matches("[0-9]{10}")||nonce==null||!nonce.matches("[A-Za-z0-9_-]{16,64}")||Math.abs(Instant.now().getEpochSecond()-Long.parseLong(timestamp))>300)throw new ApiError(org.springframework.http.HttpStatus.UNAUTHORIZED,"INTEGRATION_AUTH_REJECTED","接口签名未通过");String token=authorization.substring(7);String[] parts=token.split("\\.");UUID tenant,id;try{tenant=UUID.fromString(parts[0]);id=UUID.fromString(parts[1]);}catch(Exception e){throw new ApiError(org.springframework.http.HttpStatus.UNAUTHORIZED,"INTEGRATION_AUTH_REJECTED","接口签名未通过");}if(!IntegrationCrypto.equal(IntegrationCrypto.hmac(parts[2],IntegrationCrypto.inbound("POST",path,timestamp,nonce,body)),signature))throw new ApiError(org.springframework.http.HttpStatus.UNAUTHORIZED,"INTEGRATION_AUTH_REJECTED","接口签名未通过");String scope=switch(path){case "/api/v1/inbound/contacts"->"contacts.create";case "/api/v1/inbound/leads"->"leads.create";case "/api/v1/inbound/tickets"->"tickets.create";case "/api/v1/inbound/records"->{var query=parse(body,Query.class);yield READ_SCOPES.entrySet().stream().filter(e->e.getValue().equals(query.entityType())).findFirst().orElseThrow(ApiError::missing).getKey();}default->throw ApiError.missing();};if(idempotency==null||!idempotency.matches("[A-Za-z0-9_.:-]{1,100}"))throw ApiError.bad("请提供有效 Idempotency-Key");return b.tx.execute(st->{b.db.queryForObject("SELECT id FROM sys_tenant WHERE id=:tenant FOR UPDATE",map("tenant",tenant),UUID.class);b.context(tenant);var rs=b.rows("SELECT k.*,k.token_hash AS verification_hash FROM crm_integration_key k WHERE tenant_id=:tenant AND id=:id AND revoked_at IS NULL AND expires_at>now()",map("tenant",tenant,"id",id));if(rs.isEmpty()||!IntegrationCrypto.equal(String.valueOf(rs.getFirst().get("verificationHash")),Crypto.hash(token)))throw new ApiError(org.springframework.http.HttpStatus.UNAUTHORIZED,"INTEGRATION_AUTH_REJECTED","接口签名未通过");var k=rs.getFirst();creator(tenant,(UUID)k.get("createdByMemberId"));var owner=b.actor(tenant,(UUID)k.get("ownerMemberId"));if(epoch(owner)!=number(k,"ownerAuthVersion")||!strings(k.get("scopes")).contains(scope))throw ApiError.forbidden("接口授权已变化或范围不足");canScope(owner,scope);if(!owner.tenant().subscriptionEnd().isAfter(Instant.now()))throw ApiError.forbidden("企业订阅到期");if(b.db.queryForObject("SELECT count(*) FROM crm_integration_nonce WHERE tenant_id=:tenant AND key_id=:id AND created_at>now()-interval '1 minute'",map("tenant",tenant,"id",id),Integer.class)>=60)throw new ApiError(org.springframework.http.HttpStatus.TOO_MANY_REQUESTS,"INTEGRATION_RATE_LIMIT","接口调用过于频繁");int inserted=b.db.update("INSERT INTO crm_integration_nonce(id,tenant_id,key_id,nonce,request_hash) VALUES(:request,:tenant,:id,:nonce,:hash) ON CONFLICT DO NOTHING",map("request",UUID.randomUUID(),"tenant",tenant,"id",id,"nonce",nonce,"hash",Crypto.hash(body)));if(inserted!=1)throw ApiError.conflict("签名随机数已使用，拒绝重放");if(READ_SCOPES.containsKey(scope)){var q=parse(body,Query.class);b.audit(owner,"INTEGRATION_RECORDS_READ",q.entityType(),q.recordId(),0,trace);return q.recordId()==null?records.list(owner.session(),q.entityType(),q.page(),q.pageSize(),text(q.q()),q.year()):records.get(owner.session(),q.entityType(),q.recordId());}return switch(scope){case "contacts.create"->b.business.createContact(owner.session(),parse(body,BusinessService.ContactCreate.class),"api:"+id+":"+Crypto.hash(idempotency).substring(0,32),trace);case "leads.create"->b.business.createLead(owner.session(),parse(body,BusinessService.LeadCreate.class),"api:"+id+":"+Crypto.hash(idempotency).substring(0,32),trace);default->desk.create(owner.session(),parse(body,ServiceDeskService.TicketInput.class),"api:"+id+":"+Crypto.hash(idempotency).substring(0,32),trace);};});}
 private Map<String,Object> hook(AuthService.Actor a,UUID id){return b.one("SELECT id,name,url,events,owner_member_id,created_by_member_id,active,version,created_at,updated_at FROM crm_webhook_subscription WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",id));}
 public Object hooks(AuthService.Session s){return b.scoped(s,"integration",false,a->map("items",b.rows("SELECT h.id,h.name,h.url,h.events,h.owner_member_id,m.display_name AS owner_name,h.active,h.version,h.created_at,h.updated_at FROM crm_webhook_subscription h JOIN sys_tenant_member m ON m.tenant_id=h.tenant_id AND m.id=h.owner_member_id WHERE h.tenant_id=:tenant ORDER BY h.created_at DESC",map("tenant",a.tenant().id()))));}
 private void eventOwner(AuthService.Actor a,String event){boolean ok=switch(event.split("\\.")[0]){case "customer"->a.canReadCustomers();case "lead"->a.businessAccess().leads().read();case "opportunity"->a.businessAccess().opportunities().read();case "ticket"->a.p3Access().tickets().read();case "receipt"->a.tradeAccess().receiptRead();case "campaign"->a.p3Access().campaigns().read();default->records.allowed(a,event.split("\\.")[0].toUpperCase(Locale.ROOT),false);};if(!ok)throw ApiError.bad("归属成员无对应事件读取权限");}
 public Object saveHook(AuthService.Session s,UUID id,HookInput i,UUID trace){return b.scoped(s,"integration",true,a->{transport.validate(i.url());if(new HashSet<>(i.events()).size()!=i.events().size()||!EVENTS.containsAll(i.events()))throw ApiError.bad("Webhook 事件无效");var owner=b.actor(a.tenant().id(),i.ownerMemberId());i.events().forEach(ev->eventOwner(owner,ev));UUID selected=id==null?UUID.randomUUID():id;String secret=id==null?Crypto.token():null;var p=map("tenant",a.tenant().id(),"id",selected,"name",text(i.name()),"url",text(i.url()),"events",b.json(i.events()),"owner",i.ownerMemberId(),"epoch",epoch(owner),"creator",a.tenant().memberId(),"active",i.active());if(id==null){if(b.db.queryForObject("SELECT count(*) FROM crm_webhook_subscription WHERE tenant_id=:tenant",map("tenant",a.tenant().id()),Integer.class)>=20)throw ApiError.bad("每个企业最多20个 Webhook");p.put("secret",vault.encrypt(a.tenant().id(),selected,secret));b.db.update("INSERT INTO crm_webhook_subscription(id,tenant_id,name,url,events,owner_member_id,owner_auth_version,created_by_member_id,encrypted_secret,active) VALUES(:id,:tenant,:name,:url,cast(:events AS jsonb),:owner,:epoch,:creator,:secret,:active)",p);}else{b.version(hook(a,id),i.expectedVersion());b.db.update("UPDATE crm_webhook_subscription SET name=:name,url=:url,events=cast(:events AS jsonb),owner_member_id=:owner,owner_auth_version=:epoch,created_by_member_id=:creator,active=:active,version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id",p);}b.audit(a,id==null?"WEBHOOK_CREATED":"WEBHOOK_UPDATED","WEBHOOK",selected,id==null?0:i.expectedVersion()+1,trace);return map("hook",hook(a,selected),"oneTimeSecret",secret);});}
 public Object rotateHook(AuthService.Session s,UUID id,Decision i,UUID trace){return b.scoped(s,"integration",true,a->{var h=hook(a,id);b.version(h,i.expectedVersion());var owner=b.actor(a.tenant().id(),(UUID)h.get("ownerMemberId"));strings(h.get("events")).forEach(ev->eventOwner(owner,ev));String secret=Crypto.token();b.db.update("UPDATE crm_webhook_subscription SET encrypted_secret=:secret,owner_auth_version=:epoch,created_by_member_id=:creator,version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",id,"secret",vault.encrypt(a.tenant().id(),id,secret),"epoch",epoch(owner),"creator",a.tenant().memberId()));b.audit(a,"WEBHOOK_SECRET_ROTATED","WEBHOOK",id,i.expectedVersion()+1,trace);return map("hook",hook(a,id),"oneTimeSecret",secret);});}
 private void entity(AuthService.Actor a,String event,UUID id){switch(event.split("\\.")[0]){case "customer"->{if(!a.canReadCustomers())throw ApiError.forbidden("客户事件权限已撤销");b.customers.get(a,id);}case "lead"->{if(!a.businessAccess().leads().read())throw ApiError.forbidden("线索权限已撤销");b.business.lead(a,id);}case "opportunity"->b.sales.opportunity(a,id);case "ticket"->desk.ticket(a,id);case "receipt"->finance.receipt(a,id);case "campaign"->campaigns.campaign(a,id);default->records.get(a,event.split("\\.")[0].toUpperCase(Locale.ROOT),id,false);}}
 private AuthService.Actor authorization(UUID tenant,Map<String,Object> h,String event,UUID id){if(!Boolean.TRUE.equals(h.get("active"))||!strings(h.get("events")).contains(event))throw ApiError.forbidden("事件订阅已停用");creator(tenant,(UUID)h.get("createdByMemberId"));var owner=b.actor(tenant,(UUID)h.get("ownerMemberId"));if(epoch(owner)!=number(h,"ownerAuthVersion")||!owner.tenant().subscriptionEnd().isAfter(Instant.now()))throw ApiError.forbidden("事件归属授权已变化");entity(owner,event,id);return owner;}
 public Object queue(AuthService.Session s,int page,int size,String status,UUID subscription){page(page,size,"");if(!Set.of("","PENDING","RETRY","DELIVERED","DEAD","BLOCKED").contains(status))throw ApiError.bad("投递状态无效");return b.scoped(s,"integration",false,a->{var p=map("tenant",a.tenant().id(),"status",status,"subscription",subscription,"limit",size,"offset",((long)page-1)*size);String from=" FROM crm_webhook_outbox q JOIN crm_webhook_subscription h ON h.tenant_id=q.tenant_id AND h.id=q.subscription_id WHERE q.tenant_id=:tenant AND(:status='' OR q.status=:status) AND(cast(:subscription AS uuid) IS NULL OR q.subscription_id=:subscription)";return new BusinessService.Page<>(b.rows("SELECT q.id,q.subscription_id,h.name AS subscription_name,q.event_type,q.entity_id,q.business_version,q.status,q.attempts,q.next_attempt_at,q.last_error_code,q.delivered_at,q.created_at"+from+" ORDER BY q.created_at DESC,q.id LIMIT :limit OFFSET :offset",p),page,size,b.db.queryForObject("SELECT count(*)"+from,p,Long.class));});}
 public Object attempts(AuthService.Session s,UUID id){return b.scoped(s,"integration",false,a->{b.one("SELECT id FROM crm_webhook_outbox WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",id));return map("items",b.rows("SELECT * FROM crm_webhook_attempt WHERE tenant_id=:tenant AND outbox_id=:id ORDER BY attempt_no DESC",map("tenant",a.tenant().id(),"id",id)));});}
 public Object retry(AuthService.Session s,UUID id,UUID trace){return b.scoped(s,"integration",true,a->{var q=b.one("SELECT * FROM crm_webhook_outbox WHERE tenant_id=:tenant AND id=:id FOR UPDATE",map("tenant",a.tenant().id(),"id",id));if(!Set.of("DEAD","BLOCKED").contains(q.get("status")))throw ApiError.conflict("仅失败终止或授权阻止的投递可人工重试");var h=b.one("SELECT * FROM crm_webhook_subscription WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",q.get("subscriptionId")));authorization(a.tenant().id(),h,(String)q.get("eventType"),(UUID)q.get("entityId"));b.db.update("UPDATE crm_webhook_outbox SET status='RETRY',attempts=0,next_attempt_at=now(),last_error_code=NULL WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",id));b.audit(a,"WEBHOOK_RETRY_REQUESTED","WEBHOOK_OUTBOX",id,0,trace);return null;});}
 int deliver(UUID tenant){var ids=b.tx.execute(st->{b.context(tenant);return b.db.queryForList("SELECT id FROM crm_webhook_outbox WHERE tenant_id=:tenant AND status IN('PENDING','RETRY') AND next_attempt_at<=now() ORDER BY next_attempt_at,id LIMIT 30",map("tenant",tenant),UUID.class);});int processed=0;for(UUID id:ids){Boolean sent=b.tx.execute(st->{b.db.queryForObject("SELECT id FROM sys_tenant WHERE id=:tenant FOR UPDATE",map("tenant",tenant),UUID.class);b.context(tenant);var rs=b.rows("SELECT * FROM crm_webhook_outbox WHERE tenant_id=:tenant AND id=:id AND status IN('PENDING','RETRY') AND next_attempt_at<=now() FOR UPDATE SKIP LOCKED",map("tenant",tenant,"id",id));if(rs.isEmpty())return false;var q=rs.getFirst();var h=b.one("SELECT * FROM crm_webhook_subscription WHERE tenant_id=:tenant AND id=:id",map("tenant",tenant,"id",q.get("subscriptionId")));String outcome,error=null;Integer http=null;int attempts=((Number)q.get("attempts")).intValue()+1;try{authorization(tenant,h,(String)q.get("eventType"),(UUID)q.get("entityId"));String payload=b.json(q.get("payload")),timestamp=String.valueOf(Instant.now().getEpochSecond()),secret=vault.decrypt(tenant,(UUID)h.get("id"),(String)h.get("encryptedSecret"));http=transport.post((String)h.get("url"),payload,Map.of("X-CRM-Event-ID",id.toString(),"X-CRM-Timestamp",timestamp,"X-CRM-Signature",IntegrationCrypto.hmac(secret,IntegrationCrypto.outbound(timestamp,id,payload))));if(http>=200&&http<300)outcome="DELIVERED";else{outcome=attempts>=8?"DEAD":"RETRY";error="HTTP_STATUS_REJECTED";}}catch(ApiError e){outcome="BLOCKED";error="AUTHORIZATION_OR_DESTINATION_CHANGED";}catch(Exception e){outcome=attempts>=8?"DEAD":"RETRY";error="DELIVERY_FAILED";}var p=map("tenant",tenant,"id",id,"outcome",outcome,"http",http,"error",error,"attempts",attempts,"delay",retrySeconds(attempts));b.db.update("UPDATE crm_webhook_outbox SET status=:outcome,attempts=:attempts,next_attempt_at=now()+make_interval(secs=>:delay),last_error_code=:error,delivered_at=CASE WHEN :outcome='DELIVERED' THEN now() ELSE NULL END WHERE tenant_id=:tenant AND id=:id",p);p.put("attemptId",UUID.randomUUID());b.db.update("INSERT INTO crm_webhook_attempt(id,tenant_id,outbox_id,attempt_no,outcome,http_status,error_code) SELECT :attemptId,:tenant,:id,coalesce(max(attempt_no),0)+1,:outcome,:http,:error FROM crm_webhook_attempt WHERE tenant_id=:tenant AND outbox_id=:id",p);return true;});if(Boolean.TRUE.equals(sent))processed++;}return processed;}
 static int retrySeconds(int attempts){return Math.min(3600,15*(1<<Math.min(attempts-1,8)));}
 public Object run(AuthService.Session s){UUID tenant=b.scoped(s,"integration",true,a->a.tenant().id());return map("processed",deliver(tenant));}
}
